contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address adr, uint amount) public payable {
        require(address(this).balance >= amount);
        uint before = address(c).balance;

        uint beforeOwner = address(this).balance;
        bool reverted;
        try c.Command{value: amount}(adr, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Command is callable by the owner (this contract), and when it completes
        // without reverting, c's balance must have decreased by exactly `amount`
        // (the value forwarded to adr), independent of what adr does with it.
        if (!reverted) {
            assert(address(c).balance == before - amount + address(c).balance - (before - amount + address(c).balance) + (before - amount));
        } else {
            assert(address(c).balance == before);
        }
    }
}

