contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool asOwner) public payable {
        address owner = c.Owner();

        bool reverted;
        if (asOwner) {
            // caller is this InvMutTest contract, which deployed c and is Owner
            try c.withdraw() { reverted = false; } catch { reverted = true; }
            assert(!reverted);
        } else {
            // force caller to be a non-owner address via a helper call pattern is not allowed,
            // so instead test the Owner getter consistency and that withdraw does not revert here
            try c.withdraw() { reverted = false; } catch { reverted = true; }
            assert(owner == address(this) ? !reverted : reverted);
        }
    }

    receive() external payable {}
}

