contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Fund c with `amount` wei so the balance is nonzero before the call.
        payable(address(c)).transfer(amount);

        // Save the balance before the deciding call.
        uint balBefore = address(c).balance;

        // Make the deciding call as a plain top-level statement.
        // If the caller is not the owner (or c is at zero balance),
        // the require inside withdraw() will cause the call to revert.
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdraw()"));

        // General rule: a call to withdraw() from a non-Owner reverts.
        assert(!success || balBefore == 0);
    }

    receive() external payable {}
}

