    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(msg.value == amount);
        // fund c with some Ether (this call is not to c, so state change is on test contract)
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);

        address ownerBefore = c.Owner();
        uint256 balanceBefore = address(c).balance;

        bool reverted;
        // The test contract is the owner of c, so withdraw() by the test contract succeeds.
        // To test the non-owner revert rule, we need a different caller. Since we cannot
        // deploy another contract and msg.sender is the test contract, we call withdraw
        // through a low-level call from a different address is not possible without a helper.
        // However, the owner is always msg.sender at deployment, so the test contract is owner.
        // Calling withdraw() by the owner will succeed and set balance to 0 and owner unchanged.
        // That is the rule already accepted. The only way to test non-owner revert is if the test
        // contract could change its own address, which is impossible. Therefore, we cannot
        // directly test a non-owner call in this harness.
        // As a result, we focus on the owner path: withdraw() by the owner always succeeds and
        // leaves balance zero and owner unchanged.
        // To make the test non-trivial, we require amount > 0 so there is something to withdraw.
        require(amount > 0);
        c.withdraw();
        reverted = false;

        address ownerAfter = c.Owner();
        uint256 balanceAfter = address(c).balance;

        assert(!reverted && ownerAfter == ownerBefore && balanceAfter == 0);
    }

    receive() external payable {}
}

