        // Use a target that is the address of an existing successful pure function? Cannot deploy.
        // But we can call c itself with data that selects Owner() getter (a successful pure/view call).
        // Calling c.Owner() via Command: target = address(c), data = abi.encodeWithSignature("Owner()").
        // That call succeeds and does not change C's balance besides the forwarded value.
        address target = address(c);
        bytes memory data = abi.encodeWithSignature("Owner()");

        uint balanceBefore = address(c).balance;

        bool reverted;
        try c.Command{value: amount}(target, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = address(c).balance;

        assert(!reverted && balanceAfter == balanceBefore + amount);
    }
}

